          "eucharistic_2": {
            "title": {
              "jp": "第2奉献文の固有の叙唱"
            },
            "content": [
              {
                "text_jp": "聖なる父よ、最愛の子イエス・キリストを通して、いつどこでもあなたに感謝をささげることは、まことにとうとい大切な務め(です)。",
                "__massEditorPairKeys": {
                  "text_jp": "0:text"
                },
                "sp_jp": "司"
              },
              {
                "text_jp": "あなたはみことばによってすべてをお造りになりました。みことばである御子は、救い主、あがない主としてわたしたちに遣わされ、",
                "__massEditorPairKeys": {
                  "text_jp": "1:text"
                }
              },
              {
                "text_jp": "聖霊によって人となり、おとめマリアから生まれ、み旨を果たして、人々をあなたの聖なる民とするために、手を広げて苦難に身をゆだね、死を滅ぼして復活の栄光を現してくださいました。",
                "__massEditorPairKeys": {
                  "text_jp": "2:text"
                }
              },
              {
                "text_jp": "わたしたちは声を合わせて歌います、天使とすべての聖人とともに、あなたの栄光をたたえて。",
                "__massEditorPairKeys": {
                  "text_jp": "3:text"
                }
              }
            ]
          },
